     1→import type { NextRequest} from "next/server";
     2→import { NextResponse } from "next/server";
     3→import { headers } from "next/headers";
     4→import { auth } from "@/lib/auth";
     5→import { FavoriteEnrichmentService } from "@/lib/services/favorites/enrichment";
     6→
     7→export async function POST(request: NextRequest) {
     8→  try {
     9→    const session = await auth.api.getSession({
    10→      headers: await headers(),
    11→    });
    12→    if (!session?.user) {
    13→      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    14→    }
    15→
    16→    const { action, favoriteId, userId } = await request.json();
    17→
    18→    const enrichmentService = new FavoriteEnrichmentService();
    19→
    20→    switch (action) {
    21→      case "enrich-favorite": {
    22→        if (!favoriteId) {
    23→          return NextResponse.json({ error: "favoriteId is required" }, { status: 400 });
    24→        }
    25→
    26→        // Vérifier que le favori appartient à l'utilisateur
    27→        const { PrismaClient } = await import("@/generated/prisma");
    28→        const prisma = new PrismaClient();
    29→        const favorite = await prisma.favorite.findFirst({
    30→          where: {
    31→            id: favoriteId,
    32→            userId: session.user.id,
    33→          },
    34→        });
    35→
    36→        if (!favorite) {
    37→          return NextResponse.json({ error: "Favorite not found or access denied" }, { status: 404 });
    38→        }
    39→
    40→        const result = await enrichmentService.enrichFavoriteWithDPE(favoriteId);
    41→        return NextResponse.json(result);
    42→      }
    43→
    44→      case "enrich-user-favorites": {
    45→        const targetUserId = userId ?? session.user.id;
    46→
    47→        // Vérifier les permissions
    48→        if (targetUserId !== session.user.id && session.user.role !== "admin") {
    49→          return NextResponse.json({ error: "Unauthorized to enrich other user's favorites" }, { status: 403 });
    50→        }
    51→
    52→        const userResults = await enrichmentService.enrichUserFavorites(targetUserId);
    53→        return NextResponse.json({
    54→          success: true,
    55→          results: userResults,
    56→          total: userResults.length,
    57→          successful: userResults.filter(r => r.success).length,
    58→          failed: userResults.filter(r => !r.success).length,
    59→        });
    60→      }
    61→
    62→      case "enrich-all-without-dpe": {
    63→        // Admin seulement
    64→        if (session.user.role !== "admin") {
    65→          return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    66→        }
    67→
    68→        const allResults = await enrichmentService.enrichAllFavoritesWithoutDPE();
    69→        return NextResponse.json({
    70→          success: true,
    71→          results: allResults,
    72→          total: allResults.length,
    73→          successful: allResults.filter(r => r.success).length,
    74→          failed: allResults.filter(r => !r.success).length,
    75→        });
    76→      }
    77→
    78→      default:
    79→        return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    80→    }
    81→  } catch (error) {
    82→    console.debug("Error in DPE enrichment API:", error);
    83→    return NextResponse.json(
    84→      { error: "Internal server error" },
    85→      { status: 500 }
    86→    );
    87→  }
    88→}

