   133→          region: "Région",
   134→          publishedAt: new Date(),
   135→        },
   136→      });
   137→    }
   138→  }
   139→
   140→  // Check if already in favorites
   141→  const existingFavorite = await prisma.favorite.findUnique({
   142→    where: {
   143→      userId_propertyId: {
   144→        userId: session.user.id,
   145→        propertyId: property.id,
