   177→export async function updateFavoriteAction(request: UpdateFavoriteRequest) {
   178→  const session = await auth.api.getSession({
   179→    headers: await headers(),
   180→  });
   181→
   182→  if (!session?.user.id) {
   183→    redirect("/auth/signin");
   184→  }
   185→
   186→  const favorite = await prisma.favorite.findFirst({
   187→    where: {
   188→      id: request.id,
   189→      userId: session.user.id,
   190→    },
   191→  });
   192→
   193→  if (!favorite) {
   194→    throw new Error("Favori non trouvé");
   195→  }
   196→
   197→  const updatedFavorite = await prisma.favorite.update({
   198→    where: {
   199→      id: request.id,
   200→    },
   201→    data: {
