    10→
    11→/**
    12→ * Calculate monthly mortgage payment using the standard formula
    13→ */
    14→export function calculateMonthlyPayment(
    15→  loanAmount: number,
    16→  monthlyRate: number,
    17→  totalMonths: number,
    18→): number {
    19→  if (monthlyRate === 0) {
    20→    return loanAmount / totalMonths;
    21→  }
    22→
    23→  const payment =
    24→    (loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, totalMonths))) /
    25→    (Math.pow(1 + monthlyRate, totalMonths) - 1);
    26→
    27→  return payment;
    28→}
    29→
    30→/**
    31→ * Calculate comprehensive loan information
    32→ */
    33→export function calculateLoan(
    34→  inputs: LoanCalculationInputs,
    35→): LoanCalculationResults {
    36→  const {
    37→    propertyPrice,
    38→    loanAmount,
    39→    interestRate,
    40→    loanTermYears,
    41→    monthlyIncome,
    42→    monthlyExpenses,
    43→  } = inputs;
    44→
    45→  const monthlyRate = interestRate / 100 / 12;
    46→  const totalMonths = loanTermYears * 12;
    47→
    48→  const monthlyPayment = calculateMonthlyPayment(
    49→    loanAmount,
    50→    monthlyRate,
    51→    totalMonths,
    52→  );
    53→  const totalPayment = monthlyPayment * totalMonths;
    54→  const totalInterest = totalPayment - loanAmount;
    55→
    56→  // Calculate debt-to-income ratio
    57→  const netMonthlyIncome = monthlyIncome - monthlyExpenses;
    58→  const debtToIncomeRatio = monthlyPayment / netMonthlyIncome;
    59→
    60→  // Determine affordability status
    61→  let affordabilityStatus: LoanCalculationResults["affordabilityStatus"];
    62→  if (debtToIncomeRatio <= 0.25) {
    63→    affordabilityStatus = "excellent";
    64→  } else if (debtToIncomeRatio <= 0.33) {
    65→    affordabilityStatus = "good";
    66→  } else if (debtToIncomeRatio <= 0.4) {
    67→    affordabilityStatus = "risky";
    68→  } else {
    69→    affordabilityStatus = "too_high";
    70→  }
    71→
    72→  // Calculate notary fees
    73→  const notaryFees = calculateNotaryFees({
    74→    propertyPrice,
    75→    propertyType: "old", // Default to old property for conservative estimate
    76→    isFirstTimeBuyer: false,
    77→  });
    78→
    79→  const totalCost = propertyPrice + notaryFees.totalFees;
    80→
    81→  // Generate amortization schedule
    82→  const amortizationSchedule = generateAmortizationSchedule(
    83→    loanAmount,
    84→    monthlyRate,
    85→    totalMonths,
    86→    monthlyPayment,
    87→  );
    88→
    89→  // Generate yearly breakdown
    90→  const yearlyBreakdown = generateYearlyBreakdown(amortizationSchedule);
    91→
    92→  return {
    93→    monthlyPayment,
    94→    totalPayment,
    95→    totalInterest,
    96→    debtToIncomeRatio,
    97→    affordabilityStatus,
    98→    notaryFees: notaryFees.totalFees,
    99→    totalCost,
   100→    amortizationSchedule,
   101→    yearlyBreakdown,
   102→  };
   103→}
   104→
   105→/**
   106→ * Generate complete amortization schedule
   107→ */
   108→function generateAmortizationSchedule(
   109→  loanAmount: number,
   110→  monthlyRate: number,
   111→  totalMonths: number,
   112→  monthlyPayment: number,
   113→): AmortizationEntry[] {
   114→  const schedule: AmortizationEntry[] = [];
   115→  let remainingBalance = loanAmount;
   116→
   117→  for (let month = 1; month <= totalMonths; month++) {
   118→    const interestPayment = remainingBalance * monthlyRate;
   119→    const principalPayment = monthlyPayment - interestPayment;
   120→    remainingBalance -= principalPayment;
   121→
   122→    // Avoid negative balance due to floating point precision
   123→    if (remainingBalance < 0.01) {
   124→      remainingBalance = 0;
   125→    }
   126→
   127→    schedule.push({
   128→      month,
   129→      payment: monthlyPayment,
   130→      principal: principalPayment,
   131→      interest: interestPayment,
   132→      remainingBalance,
   133→    });
   134→  }
   135→
   136→  return schedule;
   137→}
   138→
   139→/**
   140→ * Generate yearly breakdown from amortization schedule
   141→ */
   142→function generateYearlyBreakdown(
   143→  schedule: AmortizationEntry[],
   144→): YearlyBreakdown[] {
   145→  const yearlyData: YearlyBreakdown[] = [];
   146→
   147→  for (let year = 1; year <= Math.ceil(schedule.length / 12); year++) {
   148→    const yearStart = (year - 1) * 12;
   149→    const yearEnd = Math.min(year * 12, schedule.length);
   150→    const yearEntries = schedule.slice(yearStart, yearEnd);
   151→
   152→    const totalPayments = yearEntries.reduce(
   153→      (sum, entry) => sum + entry.payment,
   154→      0,
   155→    );
   156→    const totalPrincipal = yearEntries.reduce(
   157→      (sum, entry) => sum + entry.principal,
   158→      0,
   159→    );
   160→    const totalInterest = yearEntries.reduce(
   161→      (sum, entry) => sum + entry.interest,
   162→      0,
   163→    );
   164→    const remainingBalance =
   165→      yearEntries[yearEntries.length - 1]?.remainingBalance || 0;
   166→
   167→    yearlyData.push({
   168→      year,
   169→      totalPayments,
   170→      totalPrincipal,
   171→      totalInterest,
   172→      remainingBalance,
   173→    });
   174→  }
   175→
   176→  return yearlyData;
   177→}
   178→
   179→/**
   180→ * Calculate French notary fees (frais de notaire)
   181→ */
   182→export function calculateNotaryFees(
   183→  inputs: NotaryFeesInputs,
   184→): NotaryFeesResults {
   185→  const { propertyPrice, propertyType, isFirstTimeBuyer } = inputs;
   186→
   187→  let registrationFees: number;
   188→  let stampDuty: number;
   189→
   190→  if (propertyType === "new") {
   191→    // New properties: TVA (20%) but reduced registration fees
   192→    registrationFees = propertyPrice * 0.00715; // ~0.715%
   193→    stampDuty = 0; // No stamp duty on new properties
   194→  } else {
   195→    // Old properties: Higher registration fees
   196→    if (propertyPrice <= 6500) {
   197→      registrationFees = 0;
   198→    } else if (propertyPrice <= 17000) {
   199→      registrationFees = (propertyPrice - 6500) * 0.0366;
   200→    } else if (propertyPrice <= 60000) {
   201→      registrationFees = 384.1 + (propertyPrice - 17000) * 0.0132;
   202→    } else {
   203→      registrationFees = 951.5 + (propertyPrice - 60000) * 0.0055;
   204→    }
   205→
   206→    // Add departmental tax (varies by department, using average)
   207→    registrationFees += propertyPrice * 0.038; // ~3.8%
   208→
   209→    // Stamp duty
   210→    stampDuty = propertyPrice * 0.001; // 0.1%
   211→  }
   212→
   213→  // Notary compensation (émoluments)
   214→  let notaryCompensation: number;
   215→  if (propertyPrice <= 6500) {
   216→    notaryCompensation = propertyPrice * 0.03945;
   217→  } else if (propertyPrice <= 17000) {
   218→    notaryCompensation = 256.425 + (propertyPrice - 6500) * 0.01627;
   219→  } else if (propertyPrice <= 60000) {
   220→    notaryCompensation = 427.35 + (propertyPrice - 17000) * 0.01085;
   221→  } else {
   222→    notaryCompensation = 893.9 + (propertyPrice - 60000) * 0.00814;
   223→  }
   224→
   225→  // Add VAT on notary compensation (20%)
   226→  notaryCompensation *= 1.2;
   227→
   228→  // First-time buyer reductions
   229→  if (isFirstTimeBuyer && propertyType === "old") {
   230→    registrationFees *= 0.9; // 10% reduction on registration fees
   231→  }
   232→
   233→  const notaryFees = registrationFees + notaryCompensation;
   234→  const totalFees = notaryFees + stampDuty;
   235→
   236→  const breakdown = [
   237→    {
   238→      label: "Droits d'enregistrement",
   239→      amount: registrationFees,
   240→      percentage: (registrationFees / propertyPrice) * 100,
   241→    },
   242→    {
   243→      label: "Émoluments du notaire",
   244→      amount: notaryCompensation,
   245→      percentage: (notaryCompensation / propertyPrice) * 100,
   246→    },
   247→    {
   248→      label: "Droits de timbre",
   249→      amount: stampDuty,
   250→      percentage: (stampDuty / propertyPrice) * 100,
   251→    },
   252→  ];
   253→
   254→  return {
   255→    notaryFees,
   256→    registrationFees,
   257→    stampDuty,
   258→    notaryCompensation,
   259→    totalFees,
   260→    breakdown,
   261→  };
   262→}
   263→
   264→/**
   265→ * Calculate investment metrics for rental properties
   266→ */
   267→export function calculateInvestmentMetrics(inputs: {
   268→  propertyPrice: number;
   269→  monthlyRent: number;
   270→  downPayment: number;
   271→  monthlyLoanPayment: number;
   272→  managementFees?: number;
   273→  maintenanceReserve?: number;
   274→  insurance?: number;
   275→  propertyTax?: number;
   276→}): InvestmentMetrics {
   277→  const {
   278→    propertyPrice,
   279→    monthlyRent,
   280→    downPayment,
   281→    monthlyLoanPayment,
   282→    managementFees = monthlyRent * 0.08, // 8% of rent
   283→    maintenanceReserve = monthlyRent * 0.05, // 5% of rent
   284→    insurance = 50, // €50/month average
   285→    propertyTax = (propertyPrice * 0.012) / 12, // 1.2% annual property tax
   286→  } = inputs;
   287→
   288→  const annualRent = monthlyRent * 12;
   289→  const totalMonthlyExpenses =
   290→    managementFees + maintenanceReserve + insurance + propertyTax;
   291→  const netMonthlyRent = monthlyRent - totalMonthlyExpenses;
   292→  const cashFlow = netMonthlyRent - monthlyLoanPayment;
   293→
   294→  // Gross rental yield
   295→  const rentalYield = (annualRent / propertyPrice) * 100;
   296→
   297→  // Net rental yield (after expenses, before financing)
   298→  const netAnnualRent = netMonthlyRent * 12;
   299→  const netRentalYield = (netAnnualRent / propertyPrice) * 100;
   300→
   301→  // Return on investment (based on down payment)
   302→  const annualCashFlow = cashFlow * 12;
   303→  const returnOnInvestment = (annualCashFlow / downPayment) * 100;
   304→
   305→  // Payback period (years to recover down payment)
   306→  const paybackPeriod =
   307→    annualCashFlow > 0 ? downPayment / annualCashFlow : Infinity;
   308→
   309→  return {
   310→    rentalYield,
   311→    netRentalYield,
   312→    cashFlow,
   313→    returnOnInvestment,
   314→    paybackPeriod,
   315→    monthlyRent,
   316→    annualRent,
   317→    managementFees,
   318→    maintenanceReserve,
   319→    insurance,
   320→    propertyTax,
   321→  };
   322→}
