    60→
    61→            if (priceHistory.length > 0) {
    62→              const lastPrice = priceHistory[priceHistory.length - 1].price;
    63→
    64→              if (currentPrice < lastPrice) {
    65→                const dropAmount = lastPrice - currentPrice;
    66→                const dropPercentage = (dropAmount / lastPrice) * 100;
    67→
    68→                await this.savePriceHistory(propertyId, currentPrice);
    69→
    70→                return {
    71→                  propertyId,
    72→                  property: currentProperty.data,
    73→                  previousPrice: lastPrice,
    74→                  newPrice: currentPrice,
    75→                  dropAmount,
    76→                  dropPercentage: Number(dropPercentage.toFixed(2)),
    77→                  detectedAt: new Date(),
    78→                };
    79→              }
    80→            }
    81→
    82→            // Sauvegarder le prix actuel même s'il n'y a pas de baisse
